from collections import defaultdict, deque
import random

def find_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def try_construct(n, min_deg, max_deg, min_girth, seed=42, max_attempts=50):
    random.seed(seed)

    def would_create_short_cycle(u, v, adj):
        """Check if adding edge (u,v) would create a cycle shorter than min_girth"""
        if v in adj[u]:
            return True
        dist = [-1] * n
        dist[u] = 0
        queue = deque([u])
        while queue:
            node = queue.popleft()
            if dist[node] >= min_girth - 2:
                continue
            for nb in adj[node]:
                if nb == v:
                    return True  # path of length dist[node]+1, cycle = dist[node]+2 < min_girth
                if dist[nb] == -1:
                    dist[nb] = dist[node] + 1
                    queue.append(nb)
        return False

    best = None
    best_min_deg = -1

    for attempt in range(max_attempts):
        adj = [set() for _ in range(n)]

        all_edges = [(i,j) for i in range(n) for j in range(i+1,n)]
        random.shuffle(all_edges)

        for u,v in all_edges:
            if len(adj[u]) >= max_deg or len(adj[v]) >= max_deg:
                continue
            if would_create_short_cycle(u, v, adj):
                continue
            adj[u].add(v)
            adj[v].add(u)

        degrees = [len(adj[v]) for v in range(n)]
        min_d = min(degrees)
        if min_d >= min_deg:
            edge_list = [(u,v) for u in range(n) for v in adj[u] if u < v]
            return edge_list, adj
        if min_d > best_min_deg:
            best_min_deg = min_d
            best = (degrees[:], [(u,v) for u in range(n) for v in adj[u] if u < v])

    print(f"Best min degree achieved: {best_min_deg}")
    print(f"Best degrees: {best[0]}")
    return None, None

print("Trying greedy construction...")
edges_result, adj_result = try_construct(26, 3, 5, 7, seed=42, max_attempts=100)
if edges_result:
    degrees = [len(adj_result[v]) for v in range(26)]
    girth = find_girth(adj_result, 26)
    print(f"Found! Edges: {len(edges_result)}, Degrees: {degrees}")
    print(f"Girth: {girth}")
else:
    print("Greedy failed, trying more seeds...")
    for seed in range(200):
        edges_result, adj_result = try_construct(26, 3, 5, 7, seed=seed, max_attempts=5)
        if edges_result:
            print(f"Found with seed {seed}!")
            break
